import java.util.Random;
import java.util.List;
import java.util.*;

/**
 * A simple model of a eagle.
 * Eagles age, move,contract diseases, eat prey, and die.
 *
 * @version 2022.03.02
 */
public class Eagle extends Animal
{
     // Characteristics shared by all eagles (class variables).

    // The age at which a eagle can start to breed.
    private static final int BREEDING_AGE = 15;
    // The age to which a eagle can live.
    private static final int MAX_AGE = 150;
    // The likelihood of a eagle breeding.
    private static final double BREEDING_PROBABILITY = 0.4;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 2;
    // The eagles's food level which is increased by eating prey.
    private static final int MAX_FOOD_LEVEL = 14;
    // A shared random number generator to control breeding.
    private static final Random rand = Randomizer.getRandom();
    // The food value of a single eagle.
    private static final int FOOD_VALUE = 5;
    // A set of organisms that a eagle consumes
    private static final Set<Class> DIET = new HashSet<>(Arrays.asList(Deer.class, Coyote.class, Mouse.class));

    // Implementing abstract methods to return fields to be used by the superclass
    protected double BREEDING_AGE() { return BREEDING_AGE; }
    protected int MAX_LITTER_SIZE() { return MAX_LITTER_SIZE; }
    protected double BREEDING_PROBABILITY() { return BREEDING_PROBABILITY; }
    protected int MAX_AGE() { return MAX_AGE; }
    protected int MAX_FOOD_LEVEL() { return MAX_FOOD_LEVEL; }
    protected int FOOD_VALUE() { return FOOD_VALUE; }
    protected Set<Class> DIET() { return DIET; }

    /**
     * Create a eagle. A eagle can be created as a new born (age zero
     * and not hungry) or with a random age and food level.
     * @param randomAge If true, the eagle will have random age and hunger level.
     * @param field The field currently occupied.
     * @param location The location within the field.
     * @param sex The gender of the eagle.
     */
    public Eagle(boolean randomAge, Field field, Location location, Gender sex)
    {
        super(field, location,randomAge,sex);
        this.isNocturnal = false;
    }


    /**
     * Check whether this eagle is to give birth at this step.
     * New births will be made into free adjacent locations.
     * @param newEagles A list to return newly born Eagles.
     * @param environment The environment that the eagle resides in. 
     */
    protected void giveBirth(List<Actor> newEagles, Environment environment)
    {
        // New Eagles are born into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        int births = breed();
        for(int b = 0; b < births && free.size() > 0; b++) {
            Location loc = free.remove(0);
            Gender sex = Randomizer.getRandomSex();
            Eagle young = new Eagle(false, field, loc, sex);
            newEagles.add(young);
        }
    }

    /**
     * Make this animal act - that is: make it do
     * whatever it wants/needs to do.
     * @param newAnimals A list to receive newly born animals.
     * @param environment The environment that the eagle resides in. 
     */
    public void act(List<Actor> newAnimals, Environment environment)
    {
        randomlyContractDisease();
        incrementAge();
        incrementHunger();
        if(isAlive()) {
            giveBirth(newAnimals, environment);
            // Move towards a source of food if found.
            Location newLocation = findFood(environment);
            if(newLocation == null) {
                // No food found - try to move to a free location.
                newLocation = getField().freeAdjacentLocation(getLocation());
            }
            List<Location> adjacentGrassSpots = getField().adjacentLocationsWithSpecies(getLocation(), Grass.class);

            if(newLocation != null) {
                setLocation(newLocation);
            }
            else if (adjacentGrassSpots.size() > 0) {
                getField().clear(getLocation());
                setLocation(adjacentGrassSpots.get(rand.nextInt(adjacentGrassSpots.size())));
            }
            // removing overcrowding for eagles since they're above everyone

            if(isDiseased() && getDisease().getLethalityRate() <= rand.nextDouble()){
                // every step, check if the Animal is diseased
                // if it is Diseased, and a random double is less than the lethality rate, the Animal dies
                setDead();
            }

        }
    }


    /**
     * Additional functionality that doesn't allow eagles to find food while it's raining
     * @param environment The environment that the eagle resides in. 
     * @return Location Where food was found, or null if it wasn't.
     */
    protected Location findFood(Environment environment)
    {
        while(environment.getWeather().getCurrentWeather() != WeatherType.RAINING) {
            return(super.findFood());
        }
        return null;
    }

}

import java.util.Random;

/**
 * A class representing shared characteristics of plants.
 *
 * @version 2022.03.02
 */
public abstract class Plant extends Organism implements Actor
{
    // the stages of growth for  plant
    protected int NUMBER_OF_STAGES;
    protected int STEPS_PER_STAGE = 1;
    protected int STAGE_OF_GROWTH;


    // Implementing abstract methods to return fields to be used by the superclass
    public int STEPS_PER_STAGE(){ return STEPS_PER_STAGE; }
    protected static final Random rand = Randomizer.getRandom();


    /**
     * Create a new plant at location in field.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Plant(Field field, Location location)
    {
        super(field, location);
    }

    /**
     * Checks if the plant is still able to growth
     * Returns true and increments the growth of the plant 
     * if the plant hasn't reached its final stage.
     * Returns false otherwise
     */
    public boolean incrementGrowth() {
        if(STAGE_OF_GROWTH < NUMBER_OF_STAGES){
            STAGE_OF_GROWTH++;
            return true;
        }
        return false;
    }


}

import java.util.List;

/**
 * This class models grass.
 * Grass can germinate,grow and get eaten by animals.
 * @version 2022.03.02
 */
public class Grass extends Plant
{
    private static int FOOD_VALUE;
    private static double GERMINATION_RATE = 0.1;

    /**
     * Returns the food value of the grass.
     * @return int The food value of the grass.
     */
    protected int FOOD_VALUE()
    {
        return FOOD_VALUE;
    }

    /**
     * Creates grass with a random stage of growth.
     * However, the maximum number of stages is fixed at 3,
     * and the growth rate is fixed at 2 steps per stage.
     *
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Grass(Field field, Location location)
    {
        super(field, location);

        NUMBER_OF_STAGES = 3;
        STEPS_PER_STAGE = 2;
        STAGE_OF_GROWTH = rand.nextInt(NUMBER_OF_STAGES);
        FOOD_VALUE = STAGE_OF_GROWTH;

    }


    /**
     * Make the grass act.
     * The germination rate of grass is affected by weather.
     * @param newGrass To store the newly germinated grass.
     * @param environment The environment that the grass resides in.
     */
    public void act(List<Actor> newGrass, Environment environment)
    {
        if (environment.getWeather().getCurrentWeather() == WeatherType.SUNNY){
            changeGerminationRate(0.15);
        }

        else if (environment.getWeather().getCurrentWeather() != WeatherType.SUNNY){
            changeGerminationRate(0.1);
        }

        if(isAlive() && environment.getTime().isDay() && rand.nextDouble() <= GERMINATION_RATE && (environment.getWeather().getCurrentWeather() != (WeatherType.CLOUDY))) {
            germinate(newGrass);
        }
    }

    /**
     * Check whether this grass is to germinate at this step.
     * New grass will be made into free adjacent locations.
     * @param newGrass A list to return newly made grass.
     */
    protected void germinate(List<Actor> newGrass)
    {
        // New grass are made into adjacent locations.
        // Get a list of adjacent free locations.
        Field field = getField();
        List<Location> free = field.getFreeAdjacentLocations(getLocation());
        for(int b = 0; b < free.size(); b++) {
            Location loc = free.remove(0);
            Grass young = new Grass(field, loc);
            newGrass.add(young);
        }
    }

    /**
     * Change the germination rate of grass.
     * @param newRate The new germination rate.
     */
    public void changeGerminationRate(double newRate)
    {
        if(isAlive()) {
            GERMINATION_RATE = newRate;
        }
    }

    /**
     * Increment the stage of growth of grass
     * Incrementing the growth also increases the food level by 1
     * @return true If the grass grows.
     * @return false If the grass doesn't grow.
     */
    public boolean incrementGrowth()
    {
        if(super.incrementGrowth()) {
            FOOD_VALUE++;
            return true;
        }
        return false;
    }



}

import java.awt.event.ActionListener;
import java.util.*;

/**
 * A simple predator-prey simulator, based on a rectangular field
 * containing different organisms.
 *
 * @version 2022.03.02
 */
public class Simulator
{
    private static boolean playingSimulation = false;
    private static int remainingSteps;

    private static final Random rand = Randomizer.getRandom();

    // Constants representing configuration information for the simulation.
    // The default width for the grid.
    private static final int DEFAULT_WIDTH = 240;
    // The default depth of the grid.
    private static final int DEFAULT_DEPTH = 160;

    // A map of the creation probabilities for the organisms in the simulation
    private static Map<Class<?>, Double> CREATION_PROBABILITIES = Map.ofEntries(
            Map.entry(Coyote.class, 0.010),
            Map.entry(Deer.class, 0.080),
            Map.entry(Wolf.class, 0.010),
            Map.entry(Eagle.class, 0.01),
            Map.entry(Mouse.class, 0.080),
            Map.entry(Grass.class, 0.030),
            Map.entry(Hunter.class, 0.03)

    );

    // Maximum number of hunters in the simulation
    private static final int HUNTER_LIMIT = 5;
    private static int HUNTER_COUNT = 0;


    // List of actors in the field.
    private List<Actor> actors;
    // The current state of the field.
    private Field field;
    // The current step of the simulation.
    private int step;
    // A graphical view of the simulation.
    private SimulatorView view;
    // Environment in the simulation.
    private Environment environment;


    /**
     * A simulator constructor to set the CREATION_PROBABILITY of each actor.
     * This constructor can be used to test different combinations of probabilities to find an optimal combination
     *
     * @param GrassProbability Probability of Grass being generated
     * @param DeerProbability Probability of Deer being generated
     * @param CoyoteProbability Probability of Coyote being generated
     * @param WolfProbability Probability of Wolf being generated
     * @param EagleProbability Probability of Eagle being generated
     * @param HunterProbability Probability of Hunter being generated
     * @param MouseProbability Probability of Mouse being generated
     */
    public Simulator(double GrassProbability, double DeerProbability, double CoyoteProbability, double WolfProbability, double EagleProbability, double HunterProbability, double MouseProbability){
        this(DEFAULT_WIDTH, DEFAULT_DEPTH);

        CREATION_PROBABILITIES = Map.ofEntries(
                Map.entry(Coyote.class, CoyoteProbability),
                Map.entry(Deer.class, DeerProbability),
                Map.entry(Wolf.class, WolfProbability),
                Map.entry(Eagle.class, EagleProbability),
                Map.entry(Mouse.class, MouseProbability),
                Map.entry(Grass.class, GrassProbability),
                Map.entry(Hunter.class, HunterProbability)
        );

        actors = new ArrayList<>();
        field = new Field(DEFAULT_DEPTH, DEFAULT_WIDTH);
        environment = new Environment(new Time(), new Weather());

        reset();
    }

    /**
     * Construct a simulation field with default size.
     */
    public Simulator()
    {
        this(DEFAULT_DEPTH, DEFAULT_WIDTH);
    }

    /**
     * Create a simulation field with the given size.
     * @param depth Depth of the field. Must be greater than zero.
     * @param width Width of the field. Must be greater than zero.
     */
    public Simulator(int depth, int width)
    {
        if(width <= 0 || depth <= 0) {
            System.out.println("The dimensions must be greater than zero.");
            System.out.println("Using default values.");
            depth = DEFAULT_DEPTH;
            width = DEFAULT_WIDTH;
        }

        actors = new ArrayList<>();
        field = new Field(depth, width);
        environment = new Environment(new Time(), new Weather());

        // Create a view of the state of each location in the field.
        view = new SimulatorView(depth, width);
        for(Class cls : SimulationInfo.DEFAULT_COLOR_MAP.keySet()) {
            view.setColor(cls, SimulationInfo.DEFAULT_COLOR_MAP.get(cls));
        }

        // adding additional buttons to the GUI
        view.addLongButtonListener(longButtonListener);
        view.addOneStepButtonListener(startButtonListener);
        view.addStopButtonListener(stopButtonListener);
        view.addResetButtonListener(resetButtonListener);

        // Setup a valid starting point.
        reset();
    }

    /**
     * Run the simulation from its current state for a reasonably long period,
     * (4000 steps).
     */
    public void runLongSimulation()
    {
        remainingSteps += 4000;
        simulate(remainingSteps);
    }

    /**
     * Whenever the startButton is pressed,the simulateOneStep()
     * method is called.
     */
    private ActionListener startButtonListener = e -> {
        if(playingSimulation){
            System.out.println("Stop the simulation first");
        }
        else {
            playingSimulation = true;
            simulateOneStep();
            playingSimulation = false;
        }
    };

    /**
     * Whenever the stopButton is pressed, the simulation is stopped.
     */
    private ActionListener stopButtonListener = e -> {
        playingSimulation = false;
        Thread.currentThread().interrupt();
    };

    /**
     * Whenever the resetButton is pressed, the simulation is reset.
     */
    private ActionListener resetButtonListener = e -> {
        playingSimulation = false;
        reset();
    };

    /**
     * Whenever the longButton is pressed,runLongSimulation() is called.
     */
    private ActionListener longButtonListener = e -> {
        Thread runLongSimThread = new Thread("SimulationRunThread"){
            public void run() { runLongSimulation(); }
        };

        if (!playingSimulation){
            runLongSimThread.start();
        }
        else{
            System.out.println("Stop the simulation first");
        }
    };


    /**
     * Run the simulation from its current state for the given number of steps.
     * Stop before the given number of steps if it ceases to be viable.
     * @param numSteps The number of steps to run for.
     */
    public void simulate(int numSteps)
    {
        playingSimulation = true;
        remainingSteps = numSteps;

        int backupCounter = 1;
        while(playingSimulation){
            for(int step = 1; step <= numSteps && view.isViable(field); step++) {
                simulateOneStep();
                backupCounter++;
//            delay(60);   // uncomment this to run more slowly
            }
            if(!view.isViable(field)){
                // System.out.println("STEPS COMPLETED: "+backupCounter);
                // uncomment this while optimizing for population stability
                Thread.currentThread().interrupt();
                if(backupCounter > SimulationInfo.HIGHEST_STEPS){
                    // If multiple instances of the simulation are created in the same session (for testing),
                    // the fields in SimulationInfo can be used for optimizing the default probabilities
                    SimulationInfo.HIGHEST_STEPS = backupCounter;
                    SimulationInfo.HIGHEST_STEP_PROBS = this.CREATION_PROBABILITIES;
                }
                playingSimulation = false;
                break;
            }
        }
        remainingSteps = numSteps - backupCounter;
    }

    /**
     * Run the simulation from its current state for a single step.
     * Iterate over the whole field updating the state of each
     * organism.
     */
    public void simulateOneStep()
    {
        if(!playingSimulation){ return; }
        step++;
        environment.getTime().incrementTime();
        environment.getWeather().checkWeatherChange(step);


        // Provide space for newborn animals.
        List<Actor> newActors = new ArrayList<>();
        // Let all actors act.
        for(Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
            Actor actor = it.next();
            if(actor instanceof Animal){
               if(((Animal) actor).isAwake(environment)) {
                   if(((Animal) actor).isDiseased() && ((Animal) actor).getDisease().getPropagationRate() <= rand.nextDouble()) {
                       ((Animal) actor).setDead();
                   }
                   actor.act(newActors, environment);
               }
            }
            else {
                actor.act(newActors, environment);
            }

            if(actor instanceof Plant){
                if(step % ((Plant) actor).STEPS_PER_STAGE()==0){
                    ((Plant) actor).incrementGrowth();
                }
            }

            if(! actor.isAlive()) {
                it.remove();
            }



        }
        actors.addAll(newActors);
        plantGrassInPatches();

        view.showStatus(step, environment.getWeather().getCurrentWeather().toString(), environment.getTime().getCurrentTimeString(), field);
    }

    /**
     * Randomly generate grass in free patches on the field, only if it is raining
     */
    private void plantGrassInPatches(){
        // new grass is randomly added in patches
        for(Location location:field.getRandomFreePatches(CREATION_PROBABILITIES.get(Grass.class))){
            if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Grass.class) && environment.getWeather().getCurrentWeather() == WeatherType.RAINING) {
                Grass grass = new Grass(field, location);
                actors.add(grass);
            }
        }
    }

    /**
     * Reset the simulation to a starting position.
     */
    public void reset()
    {
        step = 0;
        actors.clear();
        populate();
        environment.getTime().reset();

        // Show the starting state in the view.
        view.showStatus(step,environment.getWeather().getCurrentWeather().toString(), environment.getTime().getCurrentTimeString().toString(), field);
    }

    /**
     * Randomly populate the field with organisms.
     */
    private void populate()
    {
        Random rand = Randomizer.getRandom();
        field.clear();
        for(int row = 0; row < field.getDepth(); row++) {
            for(int col = 0; col < field.getWidth(); col++) {
                Animal.Gender sex = Randomizer.getRandomSex();
                Location location = new Location(row, col);

                if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Grass.class)) {
                    Grass grass = new Grass(field, location);
                    actors.add(grass);
                }

                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Deer.class)) {
                    Deer deer = new Deer(true, field, location, sex);
                    actors.add(deer);
                }
                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Coyote.class)) {
                    Coyote coyote = new Coyote(true, field, location, sex);
                    actors.add(coyote);
                }

                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Wolf.class)) {
                    Wolf wolf = new Wolf(true, field, location, sex);
                    actors.add(wolf);
                }
                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Eagle.class)) {
                    Eagle eagle = new Eagle(true, field, location, sex);
                    actors.add(eagle);
                }
                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Mouse.class)) {
                    Mouse mouse = new Mouse(true, field, location, sex);
                    actors.add(mouse);
                }

                else if(rand.nextDouble() <= CREATION_PROBABILITIES.get(Hunter.class)) {
                    if(!(HUNTER_COUNT >= HUNTER_LIMIT)){
                        Hunter hunter = new Hunter(field, location, environment);
                        actors.add(hunter);
                        HUNTER_COUNT++;
                    }
                }
                // else leave the location empty.
            }
        }
    }

    /**
     * Pause for a given time.
     * @param millisec  The time to pause for, in milliseconds
     */
    private void delay(int millisec)
    {
        try {
            Thread.sleep(millisec);
        }
        catch (InterruptedException ie) {
            // wake up
        }
    }


}

import java.util.*;

/**
 * Headless, view-free regression harness.
 *
 * It mirrors Simulator.populate() / simulateOneStep() / plantGrassInPatches()
 * EXACTLY (minus the Swing view) so that it drives the real model classes
 * through the same deterministic RNG sequence. Running it before and after a
 * refactor must produce an identical fingerprint, proving behaviour is
 * preserved.
 *
 * NOT part of the shipped simulation - a verification artifact only.
 */
public class RegressionHarness
{
    private static final int DEPTH = 160;
    private static final int WIDTH = 240;
    private static final int STEPS = 150;
    private static final int HUNTER_LIMIT = 5;

    private static final Map<Class<?>, Double> P = Map.ofEntries(
            Map.entry(Coyote.class, 0.010),
            Map.entry(Deer.class, 0.080),
            Map.entry(Wolf.class, 0.010),
            Map.entry(Eagle.class, 0.01),
            Map.entry(Mouse.class, 0.080),
            Map.entry(Grass.class, 0.030),
            Map.entry(Hunter.class, 0.03));

    public static void main(String[] args)
    {
        Randomizer.reset();
        Random rand = Randomizer.getRandom();

        Field field = new Field(DEPTH, WIDTH);
        Environment environment = new Environment(new Time(), new Weather());
        List<Actor> actors = new ArrayList<>();

        populate(field, environment, actors, rand);

        long fingerprint = 1469598103934665603L; // FNV-1a offset basis
        for (int step = 1; step <= STEPS; step++) {
            environment.getTime().incrementTime();
            environment.getWeather().checkWeatherChange(step);

            List<Actor> newActors = new ArrayList<>();
            for (Iterator<Actor> it = actors.iterator(); it.hasNext(); ) {
                Actor actor = it.next();
                if (actor instanceof Animal) {
                    if (((Animal) actor).isAwake(environment)) {
                        if (((Animal) actor).isDiseased()
                                && ((Animal) actor).getDisease().getPropagationRate() <= rand.nextDouble()) {
                            ((Animal) actor).setDead();
                        }
                        actor.act(newActors, environment);
                    }
                } else {
                    actor.act(newActors, environment);
                }
                if (actor instanceof Plant) {
                    if (step % ((Plant) actor).STEPS_PER_STAGE() == 0) {
                        ((Plant) actor).incrementGrowth();
                    }
                }
                if (!actor.isAlive()) {
                    it.remove();
                }
            }
            actors.addAll(newActors);
            plantGrassInPatches(field, environment, actors, rand);

            fingerprint = mix(fingerprint, signature(field, step));
        }
        System.out.println("FINGERPRINT=" + fingerprint);
    }

    private static void populate(Field field, Environment environment, List<Actor> actors, Random rand)
    {
        int hunterCount = 0;
        field.clear();
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Animal.Gender sex = Randomizer.getRandomSex();
                Location location = new Location(row, col);
                if (rand.nextDouble() <= P.get(Grass.class)) {
                    actors.add(new Grass(field, location));
                } else if (rand.nextDouble() <= P.get(Deer.class)) {
                    actors.add(new Deer(true, field, location, sex));
                } else if (rand.nextDouble() <= P.get(Coyote.class)) {
                    actors.add(new Coyote(true, field, location, sex));
                } else if (rand.nextDouble() <= P.get(Wolf.class)) {
                    actors.add(new Wolf(true, field, location, sex));
                } else if (rand.nextDouble() <= P.get(Eagle.class)) {
                    actors.add(new Eagle(true, field, location, sex));
                } else if (rand.nextDouble() <= P.get(Mouse.class)) {
                    actors.add(new Mouse(true, field, location, sex));
                } else if (rand.nextDouble() <= P.get(Hunter.class)) {
                    if (hunterCount < HUNTER_LIMIT) {
                        actors.add(new Hunter(field, location, environment));
                        hunterCount++;
                    }
                }
            }
        }
    }

    private static void plantGrassInPatches(Field field, Environment environment, List<Actor> actors, Random rand)
    {
        for (Location location : field.getRandomFreePatches(P.get(Grass.class))) {
            if (rand.nextDouble() <= P.get(Grass.class)
                    && environment.getWeather().getCurrentWeather() == WeatherType.RAINING) {
                actors.add(new Grass(field, location));
            }
        }
    }

    /** A per-step signature: counts per class + diseased count, order-independent. */
    private static long signature(Field field, int step)
    {
        Map<String, Integer> counts = new TreeMap<>();
        int diseased = 0;
        for (int row = 0; row < field.getDepth(); row++) {
            for (int col = 0; col < field.getWidth(); col++) {
                Object o = field.getObjectAt(row, col);
                if (o != null) {
                    counts.merge(o.getClass().getName(), 1, Integer::sum);
                    if (o instanceof Organism && ((Organism) o).isDiseased()) {
                        diseased++;
                    }
                }
            }
        }
        long s = step * 1000003L + diseased * 31L;
        for (Map.Entry<String, Integer> e : counts.entrySet()) {
            s = s * 1000003L + e.getKey().hashCode() * 17L + e.getValue();
        }
        return s;
    }

    private static long mix(long h, long v)
    {
        h ^= v;
        h *= 1099511628211L; // FNV prime
        return h;
    }
}
